TEST rsa_spki_import(void) {
    CvmRsaKey key;
    cvmcrypt_rsa_init(&key);
    ASSERT(cvmcrypt_rsa_import_spki(&key, spki_der, sizeof(spki_der)));
    ASSERT(!cvmcrypt_mpi_is_zero(&key.n));
    ASSERT(!cvmcrypt_mpi_is_zero(&key.e));
    ASSERT_EQ(0x10001, key.e.p[0]);
    ASSERT_EQ(2048, cvmcrypt_mpi_bitlen(&key.n));
    cvmcrypt_rsa_free(&key);
    PASS();
}

TEST rsa_pkcs1_verify_valid(void) {
    CvmRsaKey key;
    cvmcrypt_rsa_init(&key);
    ASSERT(cvmcrypt_rsa_import_spki(&key, spki_der, sizeof(spki_der)));

    ASSERT(cvmcrypt_rsa_verify_pkcs1_v15(&key, CVMCRYPT_RSA_HASH_SHA256, hello_hash,
                                         sizeof(hello_hash), valid_sig,
                                         sizeof(valid_sig)));
    cvmcrypt_rsa_free(&key);
    PASS();
}

TEST rsa_pkcs1_verify_bad(void) {
    CvmRsaKey key;
    cvmcrypt_rsa_init(&key);
    ASSERT(cvmcrypt_rsa_import_spki(&key, spki_der, sizeof(spki_der)));

    u8 bad_sig[256];
    memcpy(bad_sig, valid_sig, sizeof(valid_sig));
    bad_sig[0] ^= 0x01;
    ASSERT_FALSE(cvmcrypt_rsa_verify_pkcs1_v15(&key, CVMCRYPT_RSA_HASH_SHA256,
                                               hello_hash, sizeof(hello_hash), bad_sig,
                                               sizeof(bad_sig)));
    cvmcrypt_rsa_free(&key);
    PASS();
}

