TEST rsa_pss_verify_valid(void) {
    CvmRsaKey key;
    cvmcrypt_rsa_init(&key);
    ASSERT(cvmcrypt_rsa_import_spki(&key, spki_der, sizeof(spki_der)));

    ASSERT(cvmcrypt_rsa_verify_pss(&key, CVMCRYPT_RSA_HASH_SHA256, hello_hash,
                                   sizeof(hello_hash), test_pss_sig,
                                   sizeof(test_pss_sig)));
    cvmcrypt_rsa_free(&key);
    PASS();
}

TEST rsa_pss_verify_bad(void) {
    CvmRsaKey key;
    cvmcrypt_rsa_init(&key);
    ASSERT(cvmcrypt_rsa_import_spki(&key, spki_der, sizeof(spki_der)));

    u8 bad_sig[256];
    memcpy(bad_sig, test_pss_sig, sizeof(test_pss_sig));
    bad_sig[0] ^= 0x01;
    ASSERT_FALSE(cvmcrypt_rsa_verify_pss(&key, CVMCRYPT_RSA_HASH_SHA256, hello_hash,
                                         sizeof(hello_hash), bad_sig, sizeof(bad_sig)));
    cvmcrypt_rsa_free(&key);
    PASS();
}

TEST rsa_bad_spki(void) {
    CvmRsaKey key;
    cvmcrypt_rsa_init(&key);
    u8 garbage[10] = {0};
    ASSERT_FALSE(cvmcrypt_rsa_import_spki(&key, garbage, sizeof(garbage)));
    ASSERT_FALSE(cvmcrypt_rsa_import_spki(&key, NULL, 0));
    cvmcrypt_rsa_free(&key);
    PASS();
}

SUITE(rsa) {
    RUN_TEST(rsa_spki_import);
    RUN_TEST(rsa_pkcs1_verify_valid);
    RUN_TEST(rsa_pkcs1_verify_bad);
    RUN_TEST(rsa_pss_verify_valid);
    RUN_TEST(rsa_pss_verify_bad);
    RUN_TEST(rsa_bad_spki);
}

GREATEST_MAIN_DEFS();

int main(int argc, char** argv) {
    GREATEST_MAIN_BEGIN();
    RUN_SUITE(rsa);
    GREATEST_MAIN_END();
}
